"use client"

import * as React from "react"
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group"
import { Radio as RadioPrimitive } from "@base-ui/react/radio"

import { cn } from "@/lib/utils"
import { useSound } from "./sound-provider"

// Clicky Radio Group — circular flat radio with centered dot
// Plays click sound on selection

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const RadioGroup = React.forwardRef<
  HTMLDivElement,
  WithClassName<RadioGroupPrimitive.Props>
>(({ className, onValueChange, ...props }, ref) => {
  const { playClick } = useSound()
  return (
    <RadioGroupPrimitive
      data-slot="radio-group"
      className={cn("grid gap-2", className)}
      onValueChange={(value, eventDetails) => {
        playClick()
        onValueChange?.(value, eventDetails)
      }}
      {...props}
      ref={ref}
    />
  )
})
RadioGroup.displayName = "RadioGroup"

const RadioGroupItem = React.forwardRef<
  HTMLButtonElement,
  WithClassName<RadioPrimitive.Root.Props>
>(({ className, ...props }, ref) => {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      ref={ref}
      className={cn(
        "inline-flex items-center justify-center aspect-square h-4 w-4 rounded-full",
        "border border-border bg-background text-primary",
        "transition-all duration-base ease-out",
        "active:translate-y-px",
        "hover:border-ring/50",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:border-[var(--primary-rim)] data-checked:bg-primary",
        "data-checked:shadow-[var(--shadow-tactile-control)]",
        className
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-slot="radio-group-indicator"
        className={cn("flex items-center justify-center")}
      >
        <div className="size-full h-1.5 w-1.5 rounded-full bg-primary-foreground" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  )
})
RadioGroupItem.displayName = "RadioGroupItem"

export { RadioGroup, RadioGroupItem }
